import math
fn put_double(mut outp &u8,off int,x f64){mut bits:=u64(math.bits_from_f64(x));for k in 0..8{unsafe{outp[off+k]=u8(bits&255)};bits>>=8}}
fn read_token(v &i64,pos int,length int,mut word [32]u8) bool{for i in 0..length{mut x:=int(unsafe{v[pos+i]});if x>=65&&x<=90{x+=32};if !((x>=97&&x<=122)||(x>=48&&x<=57)||x==39){return false};word[i]=u8(x)};return true}
fn same(a [32]u8,al int,b [32]u8,bl int) bool{if al!=bl{return false};for i in 0..al{if a[i]!=b[i]{return false}};return true}
@[export:'naive_bayes_text_classification']
pub fn naive_bayes_text_classification(v &i64,n usize,outp &u8,cap usize)i64{if n<7{return -1};d64:=unsafe{v[0]};alpha:=unsafe{v[1]};if d64<2||d64>6||alpha<1||alpha>10000{return -1};d:=int(d64);mut words:=[6][32]u8{};mut lens:=[6]int{};mut labels:=[6]int{};mut seen:=[2]bool{};mut total:=[2]int{};mut pos:=2;for i in 0..d{if pos+2>int(n){return -1};lab:=unsafe{v[pos]};length:=unsafe{v[pos+1]};pos+=2;if lab<0||lab>1||length<0||length>32||pos+int(length)>int(n){return -1};if !read_token(v,pos,int(length),mut words[i]){return -1};labels[i]=int(lab);lens[i]=int(length);seen[labels[i]]=true;if length>0{total[labels[i]]++};pos+=int(length)};if pos>=int(n){return -1};qlen:=unsafe{v[pos]};pos++;if qlen<0||qlen>32||pos+int(qlen)!=int(n){return -1};mut query:=[32]u8{};if !read_token(v,pos,int(qlen),mut query)||!seen[0]||!seen[1]{return -1};mut vocab:=0;for i in 0..d{if lens[i]>0{mut fresh:=true;for j in 0..i{if lens[j]>0&&same(words[i],lens[i],words[j],lens[j]){fresh=false}};if fresh{vocab++}}};if vocab==0&&qlen>0{return -1};if cap<16||isnil(outp){return -2};mut score:=[2]f64{};for cls in 0..2{mut docs:=0;mut count:=0;for i in 0..d{if labels[i]==cls{docs++;if qlen>0&&same(words[i],lens[i],query,int(qlen)){count++}}};score[cls]=math.log(f64(docs)/f64(d));if qlen>0{sm:=f64(alpha)/1000.0;score[cls]+=math.log((f64(count)+sm)/(f64(total[cls])+sm*f64(vocab)))}};hi:=if score[0]>score[1]{score[0]}else{score[1]};a:=math.exp(score[0]-hi);b:=math.exp(score[1]-hi);put_double(mut outp,0,a/(a+b));put_double(mut outp,8,b/(a+b));return 16}
